$ErrorActionPreference = 'Stop'
$IpoBugbasePath = "C:\dbug\workspace\sessions\ERGeFmPi65M\0\db\bugbase.db"

if (-not (Test-Path $IpoBugbasePath)) {
    Write-Host "FATAL: Bugbase not found at $IpoBugbasePath" -ForegroundColor Red
    exit 1
}

Write-Host "Starting IPO Sandbox Migration..." -ForegroundColor Cyan

# CORRECTED: PowerShell uses @{} for hashtables, not {}
$columnsToAdd = @(
    @{ name = 'node'; type = 'TEXT' },
    @{ name = 'origin_distance'; type = 'INTEGER' },
    @{ name = 'adco_path_binary'; type = 'TEXT' },
    @{ name = 'father_cell_id'; type = 'TEXT' },
