)

foreach ($col in $columnsToAdd) {
    $exists = sqlite3 $IpoBugbasePath "PRAGMA table_info(role_instances);" | ForEach-Object { ($_ -split '\|')[1] } | Where-Object { $_ -eq $col.name }
    
    if ($exists) {
        Write-Host "  Column '$($col.name)' already exists. Skipping." -ForegroundColor Yellow
    } else {
        Write-Host "  Adding column '$($col.name)' ($($col.type))..." -ForegroundColor Green
        sqlite3 $IpoBugbasePath "ALTER TABLE role_instances ADD COLUMN $($col.name) $($col.type);"
    }
